function draw(){ctx.clearRect(0,0,canvas.width,canvas.height);ctx.fillStyle='#f4f6f8';ctx.fillRect(0,0,canvas.width,canvas.height);if(image)drawRaster(ctx,image,state.drawingRotation,canvas.width,canvas.height);function path(pts,color,close=false,fill=false){if(!pts.length)return;ctx.beginPath();ctx.moveTo(pts[0].x,pts[0].y);pts.slice(1).forEach(p=>ctx.lineTo(p.x,p.y));if(close)ctx.closePath();if(fill){ctx.fillStyle='rgba(15,130,200,.18)';ctx.fill()}ctx.strokeStyle=color;ctx.lineWidth=3;ctx.stroke();pts.forEach(p=>{ctx.beginPath();ctx.arc(p.x,p.y,5,0,Math.PI*2);ctx.fillStyle=color;ctx.fill()})}state.polygons.forEach((p,i)=>path(i===editRoomIndex&&editActive()?editPoints:p.points,i===editRoomIndex&&editActive()?'#e48a28':'#1476c1',true,true));if(editActive()&&editPoints){editPoints.forEach((p,i)=>{ctx.beginPath();ctx.arc(p.x,p.y,i===editVertex?10:7,0,Math.PI*2);ctx.fillStyle=i===editVertex?'#e48a28':'#fff';ctx.fill();ctx.lineWidth=2;ctx.strokeStyle='#ad6419';ctx.stroke()})}state.pipes.forEach(p=>path(p.points,'#d43636'));state.radiators.forEach(r=>{ctx.fillStyle='#bc3030';ctx.fillRect(r.x-11,r.y-6,22,12);ctx.strokeStyle='#fff';ctx.lineWidth=2;ctx.strokeRect(r.x-11,r.y-6,22,12)});for(const wall of state.wallGuides||[])path(wall.points,'#d47812');ctx.setLineDash([6,4]);for(const wall of wallCandidates)path(wall.points,'#b217a6');ctx.setLineDash([]);if(loopUI)loopUI.overlay(ctx);path(points,$('tool').value==='pipe'?'#e44':'#14a46c');document.dispatchEvent(new Event('heatloop:drawing-changed'))}

