const editControls=$('roomEditControls'),editStatus=$('roomEditStatus');
function editActive(){return $('tool').value==='editRoom'}
function editNotice(message){editStatus.textContent=message}
function editButtons(){editControls.hidden=!editActive();$('editSave').disabled=!editPoints;$('editCancel').disabled=!editPoints;$('editAddVertex').disabled=!editPoints||editVertex<0;$('editRemoveVertex').disabled=!editPoints||editVertex<0||editPoints.length<=3;canvas.style.touchAction=editActive()?'none':''}
function cancelRoomEdit(){editRoomIndex=-1;editPoints=null;editVertex=-1;editDragging=-1;editPointer=null;editNotice('Dotknij pomieszczenia, aby je edytować.');editButtons();draw()}
function selectRoomEdit(index){editRoomIndex=index;editPoints=state.polygons[index].points.map(p=>({...p}));editVertex=-1;editNotice('Edytujesz: '+state.polygons[index].name+'. Wybierz narożnik i przeciągnij go.');editButtons();draw()}
function editNearest(pos){if(!editPoints)return -1;let best=-1,dist=Infinity;editPoints.forEach((p,i)=>{const d=Math.hypot(p.x-pos.x,p.y-pos.y);if(d<dist){dist=d;best=i}});return dist<=Math.max(15,20*canvas.width/(canvas.getBoundingClientRect().width||canvas.width))?best:-1}
function segmentCross(a,b,c,d){const orient=(p,q,r)=>(q.x-p.x)*(r.y-p.y)-(q.y-p.y)*(r.x-p.x);const between=(p,q,r)=>Math.min(p.x,q.x)-1e-7<=r.x&&r.x<=Math.max(p.x,q.x)+1e-7&&Math.min(p.y,q.y)-1e-7<=r.y&&r.y<=Math.max(p.y,q.y)+1e-7;const o1=orient(a,b,c),o2=orient(a,b,d),o3=orient(c,d,a),o4=orient(c,d,b);if((o1>0&&o2<0||o1<0&&o2>0)&&(o3>0&&o4<0||o3<0&&o4>0))return true;return Math.abs(o1)<1e-7&&between(a,b,c)||Math.abs(o2)<1e-7&&between(a,b,d)||Math.abs(o3)<1e-7&&between(c,d,a)||Math.abs(o4)<1e-7&&between(c,d,b)}
