$('editAddVertex').onclick=()=>{if(!editPoints||editVertex<0)return;const a=editPoints[editVertex],b=editPoints[(editVertex+1)%editPoints.length];editPoints.splice(editVertex+1,0,{x:(a.x+b.x)/2,y:(a.y+b.y)/2});editVertex++;editNotice('Dodano narożnik. Przesuń go w odpowiednie miejsce.');editButtons();draw()};
