const offerIds=['oCompany','oSender','oPhone','oClient','oEmail','oNumber','oValid','oVat','oNotes','oShowProject'];
function offerValue(id){return $(id).type==='checkbox'?$(id).checked:$(id).value.trim()}
function offerSnapshot(){const fields=Object.fromEntries(offerIds.map(id=>[id,offerValue(id)]));const rows=qLastRows.map(([name,qty,unit,key])=>({name,qty,unit,key,price:qPrices[key],sum:qty*qPrices[key]}));const net=rows.reduce((s,r)=>s+r.sum,0),laborNet=rows.filter(r=>r.name.startsWith('Robocizna')||r.key==='bMount').reduce((s,r)=>s+r.sum,0),vat=Math.max(0,Math.min(100,parsePL(fields.oVat)||0));return {fields,rows,net,laborNet,vatAmount:net*vat/100,gross:net*(1+vat/100),date:new Date().toLocaleDateString('pl-PL'),loopPlan:state.loopPlan.linked?analyzeLoops(state):null,loopPipe:state.loopPlan.pipe,boiler:state.boiler.linked?analyzeBoiler(state):null,rooms:[...state.rooms,...state.polygons].map(r=>({name:r.name,area:r.area,power:r.area*r.load}))}}
function offerHtml(o){const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const f=o.fields;const date=new Date();date.setDate(date.getDate()+Math.max(1,Number(f.oValid)||14));return `<article class="offer-doc"><header class="offer-head"><div><h1>HeatLoop | OFERTA</h1><b>${esc(f.oCompany||'Instalator')}</b><p>${esc(f.oSender)} ${esc(f.oPhone)}</p></div><div>Nr: ${esc(f.oNumber||'—')}<br>Data: ${esc(o.date)}<br>Ważna do: ${esc(date.toLocaleDateString('pl-PL'))}</div></header><h2>Wycena instalacji grzewczej</h2><p><b>Klient:</b> ${esc(f.oClient||'—')}<br><b>E-mail:</b> ${esc(f.oEmail||'—')}</p><table><thead><tr><th>Materiał</th><th>Ilość</th><th>Cena netto</th><th>Wartość netto</th></tr></thead><tbody>${o.rows.map(r=>`<tr><td>${esc(r.name)}</td><td>${qFmt(r.qty)} ${esc(r.unit)}</td><td>${qFmt(r.price)} zł</td><td>${qFmt(r.sum)} zł</td></tr>`).join('')}</tbody></table><div class="offer-sums"><p>Materiały netto: <b>${qFmt(o.net-o.laborNet)} zł</b></p><p>Robocizna netto: <b>${qFmt(o.laborNet)} zł</b></p><p>Razem netto: <b>${qFmt(o.net)} zł</b></p><p>VAT (${qFmt(o.vatAmount?Number(f.oVat):0)}%): <b>${qFmt(o.vatAmount)} zł</b></p><h2>Razem brutto: ${qFmt(o.gross)} zł</h2></div>${f.oShowProject?`<h3>Pomieszczenia projektu</h3><table><thead><tr><th>Pomieszczenie</th><th>Powierzchnia</th><th>Moc orientacyjna</th></tr></thead><tbody>${o.rooms.map(r=>`<tr><td>${esc(r.name)}</td><td>${qFmt(r.area)} m²</td><td>${qFmt(r.power)} W</td></tr>`).join('')}</tbody></table>`:''}${o.loopPlan?`<h3>Rozdzielacze — pętle (${esc(o.loopPipe)})</h3><table><thead><tr><th>Sekcja / pomieszczenie</th><th>Strefa</th><th>Długość z dojściami</th><th>Przepływ</th></tr></thead><tbody>${o.loopPlan.rows.map(l=>`<tr><td>${esc(loopLabel(l))} — ${esc(l.room)}</td><td>${esc(l.zone)}</td><td>${qFmt(l.length)} m (${l.drawn?'trasa':'szacunek'})</td><td>${qFmt(l.flow/60)} l/min</td></tr>`).join('')}</tbody></table><p>Wstępne przepływy dla wody, według zadanej mocy i ΔT. Bez weryfikacji strat ciśnienia i wydajności posadzki.</p>`:''}${o.boiler?`<h3>Kotłownia — dobór wstępny</h3><p>Zapotrzebowanie CO: ${qFmt(o.boiler.baseKW)} kW; wariant porównawczy z zapasem: ${qFmt(o.boiler.comparisonKW)} kW. Zakres i ceny wymagają potwierdzenia dla wybranych urządzeń. Nie jest to projekt montażowy ani dobór zabezpieczeń.</p>`:''}<h3>Uwagi</h3><p class="offer-notes">${esc(f.oNotes||'Wycena obejmuje materiały wyszczególnione powyżej. Nie obejmuje robocizny, o ile nie wskazano inaczej.')}</p><p class="offer-disclaimer">${state.controls.enabled?'Sterowanie TECH: ceny katalogowe sprawdzone 15.10.2026 lub zmienione przez instalatora; bez przewodów, montażu i dodatkowych zabezpieczeń. ':''}Dobór hydrauliczny i ilości należy zweryfikować przed realizacją. Oferta sporządzona na podstawie danych wprowadzonych do HeatLoop.</p><footer>HeatLoop © 2026. Wszelkie prawa autorskie zastrzeżone. Właściciel: Rafał Sroczyński.</footer></article>`}
function printOffer(){if(!validateOffer())return;const w=window.open('','_blank');if(!w){$('oStatus').textContent='Zezwól na wyskakujące okna lub użyj pobierania PDF.';return}w.document.write(`<!doctype html><html lang="pl"><head><meta charset="utf-8"><title>Oferta HeatLoop</title><style>body{font:14px Arial,sans-serif;color:#152b38;margin:30px}.offer-head{display:flex;justify-content:space-between;border-bottom:3px solid #176b82;padding-bottom:20px}h1{font-size:23px}h2{font-size:19px}table{width:100%;border-collapse:collapse;margin:20px 0}td,th{padding:9px;border-bottom:1px solid #ddd;text-align:left}th{background:#eef4f6}.offer-sums{text-align:right}.offer-notes{white-space:pre-wrap}.offer-disclaimer,footer{font-size:11px;color:#555;margin-top:25px}@page{size:A4;margin:14mm}</style></head><body>${offerHtml(offerSnapshot())}<script>window.onload=()=>setTimeout(()=>window.print(),300)<\/script></body></html>`);w.document.close()}
let pdfLibPromise;
function loadPdfLib(){if(window.html2pdf)return Promise.resolve(window.html2pdf);if(!pdfLibPromise){let script;pdfLibPromise=new Promise((resolve,reject)=>{script=document.createElement('script');const timer=setTimeout(()=>reject(Error('Przekroczono czas pobierania biblioteki PDF. Spróbuj ponownie.')),15000);script.src='https://cdnjs.cloudflare.com/ajax/libs/html2pdf.js/0.10.1/html2pdf.bundle.min.js';script.onload=()=>{clearTimeout(timer);if(typeof window.html2pdf==='function')resolve(window.html2pdf);else reject(Error('Biblioteka PDF jest niedostępna. Spróbuj ponownie.'))};script.onerror=()=>{clearTimeout(timer);reject(Error('Nie udało się pobrać biblioteki PDF. Sprawdź połączenie internetowe.'))};document.head.append(script)}).catch(error=>{script?.remove();pdfLibPromise=undefined;throw error})}return pdfLibPromise}
async function createOfferPdf(){if(!validateOffer())throw Error('Uzupełnij poprawnie dane oferty.');const lib=await loadPdfLib(),holder=document.createElement('div');holder.className='pdf-render';holder.innerHTML=offerHtml(offerSnapshot());document.body.append(holder);try{const blob=await lib().set({margin:12,filename:'HeatLoop-oferta.pdf',image:{type:'jpeg',quality:0.98},html2canvas:{scale:2,useCORS:true,backgroundColor:'#ffffff'},jsPDF:{unit:'mm',format:'a4',orientation:'portrait'},pagebreak:{mode:['css','legacy']}}).from(holder).outputPdf('blob');return blob}finally{holder.remove()}}
function offerFilename(){return 'HeatLoop-oferta-'+(offerValue('oNumber')||'klient').replace(/[^a-zA-Z0-9_-]/g,'_')+'.pdf'}
$('oPdf').onclick=async()=>{const b=$('oPdf');b.disabled=true;$('oStatus').textContent='Tworzenie PDF…';try{const pdf=await createOfferPdf();download(pdf,offerFilename());$('oStatus').textContent='PDF przygotowany. Na iPhonie wybierz Zapisz w Plikach w menu pobierania.'}catch(e){$('oStatus').textContent=e.message+' Możesz użyć przycisku „Drukuj / Zapisz jako PDF”.'}finally{b.disabled=false}};
$('oPrint').onclick=printOffer;
$('oShare').onclick=async()=>{const b=$('oShare');b.disabled=true;$('oStatus').textContent='Przygotowywanie załącznika…';try{const blob=await createOfferPdf(),file=new File([blob],offerFilename(),{type:'application/pdf'});if(navigator.canShare&&navigator.canShare({files:[file]})){await navigator.share({files:[file],title:'Oferta HeatLoop',text:'Oferta przygotowana przez '+(offerValue('oCompany')||'instalatora')});$('oStatus').textContent='Otwarto udostępnianie. Wybierz aplikację e-mail i sprawdź adres nadawcy oraz odbiorcy.'}else{download(blob,offerFilename());$('oStatus').textContent='PDF pobrany. Dołącz go ręcznie w swojej aplikacji e-mail; przeglądarka nie obsługuje udostępniania plików.'}}catch(e){$('oStatus').textContent=e.name==='AbortError'?'Udostępnianie anulowane.':e.message}finally{b.disabled=false}};

// Walidacja danych oferty oraz obsługa przecinka dziesiętnego w polach liczbowych.
function validateOffer(){if([...$('qRows').querySelectorAll('input')].some(input=>!input.checkValidity())){$('oStatus').textContent='Popraw nieprawidłową cenę materiału przed przygotowaniem oferty.';return false}const vat=parsePL($('oVat').value),valid=parsePL($('oValid').value);const ok=Number.isFinite(vat)&&vat>=0&&vat<=100&&Number.isInteger(valid)&&valid>=1&&valid<=3650&&qLastRows.length>0;const missingPrices=qLastRows.filter(row=>row[1]>0&&(!Number.isFinite(qPrices[row[3]])||qPrices[row[3]]<=0));if(missingPrices.length){$('oStatus').textContent='Uzupełnij ceny materiałów i stawki robocizny (także izolacji oraz kształtek) przed wygenerowaniem oferty PDF.';return false}if(!ok){$('oStatus').textContent='Podaj VAT od 0 do 100% oraz ważność oferty od 1 do 3650 dni. Sprawdź też dane wyceny.';return false}if($('oSender').value.trim()&&!$('oSender').checkValidity()||$('oEmail').value.trim()&&!$('oEmail').checkValidity()){$('oStatus').textContent='Sprawdź adres e-mail instalatora lub klienta.';return false}return true}
// W polach tekstowych można wprowadzić 0,5 lub 0.5; puste pole nie jest traktowane jak zero.
['roomArea','roomLoad','roomSpacing','defaultLoad','defaultSpacing','qLoops','qFloorLength','qReserve','qPower','qDt','qVmax','qSupply','qReturn','oVat','oValid'].forEach(id=>{const el=$(id);if(!el)return;el.type='text';el.inputMode='decimal';el.autocomplete='off';el.addEventListener('blur',()=>{const value=parsePL(el.value);if(Number.isFinite(value))el.value=String(value).replace('.',',')})});
techUI=mountControls(state,renderQuote);renderQuote();

loopUI=mountLoopPlanner(state,{
 render,
 changed:()=>renderQuote(),
 openDrawing:()=>{openTab('drawing');$('heatingSystem').value=$('heatingSystem').value||'wet';$('heatingSystem').dispatchEvent(new Event('change'));$('canvas').scrollIntoView?.({block:'center'})},
 startRoute:m=>{points=[{...m}];$('tool').value='loopRoute';draw()},
 placeManifold:()=>{points=[];$('tool').value='manifold';draw()},
 exportCsv:rows=>download(new Blob(['\ufeff'+rows.map(row=>row.map(csvCell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}),'heatloop-petle.csv')
});render();

boilerUI=mountBoiler(state,qPrices,{
 changed:()=>renderQuote(),
 exportCsv:rows=>download(new Blob(['\ufeff'+rows.map(row=>row.map(csvCell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}),'heatloop-kotlownia.csv')
});

// Explicit local preview; never expose state or quote fields to the helper.
document.addEventListener('heatloop:preview-request',event=>{
 if(typeof event.detail?.provide!=='function')return;
 let analysis=null;try{analysis=analyzeLoops(state);}catch{/* Partial drafts still get a basic preview. */}
 const snapshot=drawingHelpSnapshot(state,{analysis,points,wallCandidates,tool:$('tool').value,capture:()=>{const thumbnail=document.createElement('canvas');thumbnail.width=720;thumbnail.height=504;thumbnail.getContext('2d').drawImage(canvas,0,0,720,504);return thumbnail.toDataURL('image/jpeg',0.65);}});
 event.detail.provide({snapshot,advice:drawingHelpAdvice(snapshot)});
});
document.addEventListener('heatloop:preview-navigate',event=>{if(['drawing','manual','loops'].includes(event.detail?.module))openTab(event.detail.module);if(event.detail?.action==='detect-walls')$('detectWalls').click();});

function resetWallList(){if(!$('wallCandidates'))return;$('wallCandidates').replaceChildren();$('acceptWalls').disabled=true;$('wallStatus').textContent='';}
for(const [id,turn]of [['rotateLeft',-90],['rotateRight',90]])$(id).onclick=()=>{try{if(editPoints)cancelRoomEdit();points=rotateDrawing(state,turn,{points});wallCandidates=[];resetWallList();render();$('wallStatus').textContent='Obrót: '+state.drawingRotation+'°. Sprawdź skalę i położenie elementów na rzucie.';}catch(err){$('wallStatus').textContent=err.message;}};
$('detectWalls').onclick=async()=>{
 if(!image){$('wallStatus').textContent='Najpierw wczytaj rzut PNG/JPG/PDF.';return;}
 const sourceImage=image,sourceRotation=state.drawingRotation;$('detectWalls').disabled=true;$('wallStatus').textContent='Wykrywam propozycje ścian lokalnie…';await new Promise(resolve=>setTimeout(resolve,0));
 try{if(image!==sourceImage||state.drawingRotation!==sourceRotation)return;const raw=document.createElement('canvas');raw.width=1000;raw.height=700;const rc=raw.getContext('2d',{willReadFrequently:true});rc.fillStyle='white';rc.fillRect(0,0,1000,700);drawRaster(rc,image,state.drawingRotation);wallCandidates=detectWallCandidates(rc.getImageData(0,0,1000,700),{threshold:n($('wallThreshold').value)});resetWallList();
 wallCandidates.forEach((wall,i)=>{const label=document.createElement('label'),input=document.createElement('input');input.type='checkbox';input.checked=true;input.dataset.wallIndex=String(i);label.append(input,document.createTextNode(' Propozycja '+(i+1)+' — '+(wall.axis==='horizontal'?'pozioma':'pionowa')));$('wallCandidates').append(label);});$('acceptWalls').disabled=!wallCandidates.length;
 render();$('wallStatus').textContent=wallCandidates.length?'Znaleziono '+wallCandidates.length+' propozycji (maks. 200). Odznacz błędne linie, następnie zatwierdź.':'Nie znaleziono ścian dla tego progu. Spróbuj zmienić próg lub obrysuj pomieszczenia ręcznie.';
 }catch(err){wallCandidates=[];resetWallList();draw();$('wallStatus').textContent='Nie udało się wykryć ścian: '+err.message;}finally{$('detectWalls').disabled=false;}
};
$('acceptWalls').onclick=()=>{const selected=[...$('wallCandidates').querySelectorAll('input:checked')].map(input=>wallCandidates[Number(input.dataset.wallIndex)]).filter(Boolean);if(!selected.length){$('wallStatus').textContent='Zaznacz przynajmniej jedną propozycję.';return;}if(state.wallGuides.length&&!confirm('Zastąpić zatwierdzone linie pomocnicze nowymi?'))return;state.wallGuides=normalizeWallGuides(selected);wallCandidates=[];resetWallList();render();$('wallStatus').textContent='Zatwierdzono '+state.wallGuides.length+' linii pomocniczych. Obrysy pomieszczeń wykonaj i sprawdź osobno.';};
$('clearWalls').onclick=()=>{state.wallGuides=[];wallCandidates=[];resetWallList();render();};

